-- Athena saved query (Product_B2C_Intl)
-- ID: e81ec85a-1e20-4503-8445-3a86e7a97fd9
-- Name: Free Seat Data at Seat level - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH base_tins AS ( SELECT DISTINCT CAST(DATE_TRUNC('day', at_timezone(time_of_event, 'Asia/Kolkata')) AS DATE) AS doi, CASE WHEN sales_channel = 'RB:MOBILEWEB#droidapp' THEN 'Android' WHEN sales_channel = 'RB:MOBILEWEB#iosapp' THEN 'iOS' WHEN sales_channel = 'WEBDIRECT' THEN 'Desktop' WHEN sales_channel = 'MOBILEWEB' THEN 'MobWeb' END AS sales_channel, operator_id, CASE WHEN operator_id = 15443 THEN 'WBSTC' WHEN operator_id = 16426 THEN 'WBTC (CTC)' WHEN operator_id = 32272 THEN 'SBSTC' WHEN operator_id = 24978 THEN 'NBSTC' ELSE 'NA' END AS rtc_name, tin, seat_price, travellers_gender FROM transaction.bus_ticket_events WHERE time_of_event >= TIMESTAMP '2026-06-03 18:30:00' AND time_of_event < TIMESTAMP '2026-06-07 18:30:00' AND country_code = 'IND' AND operator_id IN (15443, 16426, 32272, 24978) AND sales_channel IN ( 'RB:MOBILEWEB#iosapp', 'RB:MOBILEWEB#droidapp', 'WEBDIRECT', 'MOBILEWEB' ) AND status = 'CONFIRMED' AND event_class = 2 AND event_type = 101 ), seat_level AS ( SELECT b.doi, b.sales_channel, b.operator_id, b.rtc_name, b.tin, g.gender, p.price FROM base_tins b CROSS JOIN UNNEST(b.travellers_gender) WITH ORDINALITY AS g(gender, pos) CROSS JOIN UNNEST(b.seat_price) WITH ORDINALITY AS p(price, pos2) WHERE pos = pos2 ) SELECT doi, sales_channel, operator_id, rtc_name, COUNT( CASE WHEN UPPER(gender) = 'FEMALE' AND price > 0 THEN 1 END ) AS paid_female_seats, COUNT( CASE WHEN UPPER(gender) = 'FEMALE' AND price = 0 THEN 1 END ) AS free_female_seats, COUNT( CASE WHEN UPPER(gender) = 'MALE' AND price > 0 THEN 1 END ) AS paid_male_seats, COUNT( CASE WHEN UPPER(gender) = 'MALE' AND price = 0 THEN 1 END ) AS free_male_seats FROM seat_level GROUP BY 1,2,3,4 ORDER BY 1,2,3
